const i = $('Trigger').first().json;
const r = $input.first().json;
const row = r && r.order_id ? r : null;  

const risk = Number(i.risk_score || 0);
const refunds90 = Number(i.refunds_last_90d || 0);
const confirmed = String(i.confirmed) === 'true';
const approved = false;                  

let d = { decision: 'decline', route: 'decline', refund_amount: 0, reasons: '' };

if (!row) {
  d.reasons = 'Order not found for this customer';
} else if (row.refunded === 'yes' || Number(row.prior_actions) > 0) {
  d.reasons = 'Already refunded or returned';
} else if (row.order_status === 'cancelled') {
  d.reasons = 'Order is already cancelled';
} else if (risk >= Number(row.risk_score_escalate) || refunds90 >= Number(row.serial_refund_threshold)) {
  d = { decision: 'human', route: 'human', refund_amount: 0, reasons: 'Risk gate: customer needs human review' };
} else if (!['payment_pending', 'packed'].includes(row.order_status)) {
  d.reasons = 'Already shipped or delivered; cannot cancel';
} else {
  const refund = row.payment_method === 'cod' ? 0 : Number(row.amount) + Number(row.shipping_fee);
  let route = 'human';
  const reasons = ['Cancellation'];
  if (refund <= Number(row.auto_limit)) {
    if (Number(row.auto_actions_30d) >= Number(row.max_auto_actions_30d)) {
      route = 'approval';
      reasons.push('Auto-action limit reached');
    } else {
      route = 'auto';
    }
  } else if (refund <= Number(row.approval_limit)) {
    route = 'approval';
  }
  d = {
    decision: route === 'human' ? 'human' : 'eligible',
    route,
    refund_amount: refund,
    reasons: reasons.join('; ')
  };
}


let allowed = false, already_done = false, message = 'OK';
if (!confirmed) {
  message = 'The customer has not confirmed yet.';
} else if (d.decision !== 'eligible') {
  already_done = d.reasons.toLowerCase().includes('already');
  message = 'Not allowed: ' + d.reasons;
} else if (d.route === 'auto' || (d.route === 'approval' && approved)) {
  allowed = true;
} else {
  message = 'This needs approval or a person. Escalate instead.';
}

return [{
  json: {
    ...d,
    allowed,
    already_done,
    message,
    currency: row ? row.currency : '',
    policy_version: row ? row.policy_version : ''
  }
}];

